    # calcualte SNP+SV PRS, here we used the absolute value of beta to penalize models with negative beta
    # however, given all models have positive beta, this is equivalent to just using beta
	df_merge$SCORE_MERGE <- df_merge$SCORE_SNP * abs(BETA_SNP) + df_merge$SCORE_SV * abs(BETA_SV)
    
    # fit logistic regression on SNP + SV scores
	regression_full <- paste0(pheno, " ~ SCORE_MERGE + Age + Sex + PC1 + PC2 + PC3")
	regression_null <- paste0(pheno, " ~ Age + Sex + PC1 + PC2 + PC3")
	fit_full <- glm(regression_full, data = df_merge, family = "binomial")
