	df_summary_snp_sv_condition <- bind_rows(df_summary_snp_sv_condition, df_stat)
}

write_tsv(df_summary_snp_sv_condition, 'output/fig3ab_prs/SNP_SV_condition_models.txt')

# visualization
df_plot <- bind_rows(filter(df_summary_snp, threshold == 0.01) %>% select(PRS_type, r2_PRS, AUC),
                     filter(df_summary_sv, threshold == 0.05) %>% select(PRS_type, r2_PRS, AUC),
                     mutate(df_summary_snp_sv, PRS_type="SNP+SV") %>% select(PRS_type, r2_PRS, AUC),
                     mutate(df_summary_snp_sv_condition, PRS_type="SNPadj+SV") %>% select(PRS_type, r2_PRS, AUC))
df_plot <- mutate(df_plot, PRS_type = factor(PRS_type, levels=c("SNP", "SV", "SNP+SV", "SNPadj+SV")))

pdf("output/fig3ab_prs/fig3a_prs_r2.pdf")
ggplot(filter(df_plot, PRS_type!="SNPadj+SV"), aes(PRS_type, r2_PRS, color=PRS_type)) + 
    geom_boxplot(outlier.shape = NA, color="black") + 
    geom_jitter(position=position_jitter(0.2))
dev.off()

