# counts are allele counts here, we need to divide by 2 to get variant counts
df_summary_snp %>% group_by(PRS_type, threshold) %>% 
    summarise(r2_PRS_mean=mean(r2_PRS, na.rm=TRUE),
              beta=mean(BETA, na.rm=TRUE), 
              count=mean(Count/2, na.rm=TRUE), 
              AUC_mean=mean(AUC, na.rm=TRUE)) %>% 
    ungroup() %>% print()

df_summary_sv %>% group_by(PRS_type, threshold) %>% 
